# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ABDESTİN FARZLARI, SÜNNETLERİ VE BOZAN DURUMLAR</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Abdestin 4 Farzı (Mâide, 6)</text>\n  <text x="125" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">1. Yüzü bir kez yıkamak</text>\n  <text x="125" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">2. Kolları dirseklerle</text>\n  <text x="125" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">birlikte yıkamak</text>\n  <text x="125" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">3. Başın dörtte birini</text>\n  <text x="125" y="192" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">mesh etmek (ıslak elle)</text>\n  <text x="125" y="218" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">4. Ayakları topuklarla yıkamak</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Abdestin Sünnetleri</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#14532d">• Niyet etmek ve Eûzü-Besmele</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#14532d">• Elleri bileklere kadar yıkamak</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11" fill="#14532d">• Ağız ve burnu 3\'er kez yıkamak</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11" fill="#14532d">• Kulakları ve boynu mesh etmek</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11" fill="#14532d">• Organları 3\'er kez ve sağdan</text>\n  <text x="350" y="204" text-anchor="middle" font-size="11" fill="#14532d">başlayarak sırayla yıkamak</text>\n  <text x="350" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• Suyu israf etmemek</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Abdesti Bozan Durumlar</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#7f1d1d">• Tuvalet ihtiyacını gidermek</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11" fill="#7f1d1d">veya yellenecek durum olması</text>\n  <text x="575" y="140" text-anchor="middle" font-size="11" fill="#7f1d1d">• Vücuttan kan, irin akması</text>\n  <text x="575" y="162" text-anchor="middle" font-size="11" fill="#7f1d1d">• Ağız dolusu kusmak</text>\n  <text x="575" y="184" text-anchor="middle" font-size="11" fill="#7f1d1d">• Uyuyakalmak veya bayılmak</text>\n  <text x="575" y="206" text-anchor="middle" font-size="11" fill="#7f1d1d">• Namazda yanındakinin</text>\n  <text x="575" y="222" text-anchor="middle" font-size="11" fill="#7f1d1d">duyacağı kadar sesli gülmek</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GUSÜL (BOY ABDESTİ) VE TEYEMMÜMÜN YAPILIŞI</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Guslün (Boy Abdestinin) 3 Farzı</text>\n  <text x="180" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#075985">1. Ağza bol su alıp boğaza kadar çalkalamak</text>\n  <text x="180" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#075985">2. Burna genze kadar su çekip temizlemek</text>\n  <text x="180" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#075985">3. Bütün vücudu kuru yer kalmayacak</text>\n  <text x="180" y="178" text-anchor="middle" font-size="12" font-weight="bold" fill="#075985">şekilde tepeden tırnağa yıkamak</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" fill="#0c4a6e">Cuma ve bayram namazları için gusül almak sünnettir.</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Teyemmümün 2 Farzı (Su Bulunmadığında)</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. Niyet etmek (Teyemmümde niyet FARZDIR)</text>\n  <text x="520" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. Temiz toprağa (veya toprak cinsi yüzeye) elleri</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">iki kez vurup yüzü ve kolları mesh etmek:</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#78350f">• 1. Vuruş: Parmaklar silkelenir, yüzün tamamı mesh edilir.</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11" fill="#78350f">• 2. Vuruş: Sağ ve sol kol dirseklerle birlikte mesh edilir.</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Su bulunduğunda veya abdest bozulduğunda teyemmüm bozulur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM\'DA MADDİ VE MANEVİ TEMİZLİK (TAHARET) ANLAYIŞI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Hadesten ve Necasetten Taharet</text>\n  <text x="182" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">• Hadesten Taharet (Hükmi Temizlik):</text>\n  <text x="182" y="118" text-anchor="middle" font-size="11" fill="#6b21a8">Gözle görülmeyen abdestsizlik durumundan abdest,</text>\n  <text x="182" y="136" text-anchor="middle" font-size="11" fill="#6b21a8">gusül veya teyemmüm ile temizlenmektir.</text>\n  <text x="182" y="162" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">• Necasetten Taharet (Maddi Temizlik):</text>\n  <text x="182" y="180" text-anchor="middle" font-size="11" fill="#6b21a8">Bedeni, elbiseyi ve ibadet edilecek yeri gözle</text>\n  <text x="182" y="198" text-anchor="middle" font-size="11" fill="#6b21a8">görülen kirlerden arındırmaktır.</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Manevi Temizlik ve Çevre Bilinci</text>\n  <text x="517" y="100" text-anchor="middle" font-size="11" fill="#14532d">• Kalbi yalan, kibir, kıskançlık, gıybet ve</text>\n  <text x="517" y="118" text-anchor="middle" font-size="11" fill="#14532d">kötü düşüncelerden arındırmak manevi temizliktir.</text>\n  <text x="517" y="144" text-anchor="middle" font-size="11" fill="#14532d">• Tövbe ve istiğfar kalbi manevi kirlerden temizler.</text>\n  <text x="517" y="170" text-anchor="middle" font-size="11" fill="#14532d">• Ağız-diş sağlığı, tırnak kesimi ve çevre temizliği</text>\n  <text x="517" y="188" text-anchor="middle" font-size="11" fill="#14532d">Peygamberimizin (s.a.v.) önemli sünnetlerindendir.</text>\n  <text x="517" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">«Temizlik imanın yarısıdır.» (Hadis-i Şerif)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
